mapper.select:
select
  AB.article_id
from article_bookmarks AB
where AB.article_id in

    #{item}

and AB.user_id = #{currentUser.id}

select
  AB.article_id articleBookmarkArticleId,
  AB.user_id articleBookmarkUserId,
  AB.created_at articleBookmarkCreatedAt
from article_bookmarks AB
join articles A on A.id = AB.article_id

    AB.user_id = #{userId}

        AND (AB.created_at < #{page.cursor.bookmarkedAt}

            OR (AB.created_at = #{page.cursor.bookmarkedAt} AND AB.article_id < #{page.cursor.articleId})
        )


        AND (AB.created_at > #{page.cursor.bookmarkedAt}

            OR (AB.created_at = #{page.cursor.bookmarkedAt} AND AB.article_id > #{page.cursor.articleId})
        )



    order by AB.created_at desc, AB.article_id desc


    order by AB.created_at asc, AB.article_id asc

limit #{page.queryLimit}
